function safe(file){let current=root;for(const part of file.split('/')){current=path.join(current,part);try{if(fs.lstatSync(current).isSymbolicLink())stop('Symbolic link at '+file);}catch(e){if(e.code!=='ENOENT')throw e;}}}
for(const file of [...Object.keys(files),'.stem-tutor-backups'])safe(file);
const changed=[],conflicts=[];
for(const [file,content] of Object.entries(files)){
 const current=fs.existsSync(file)?fs.readFileSync(file,'utf8'):null;
 if(current!==null&&normalize(current)===normalize(content))continue;
 if((current===null&&expected[file]!==null)||(current!==null&&(expected[file]===null||hash(current)!==expected[file])))conflicts.push(file);
 else changed.push(file);
}
if(conflicts.length)stop('These files differ from the project state after patch-canvas-first-paint-classroom.sh. Keep your edits and request a refreshed patch:\n'+conflicts.join('\n'));
if(!changed.length){console.log('Canvas repaint fixes and the minimized AI prompt are already installed.');process.exit(0);}
fs.mkdirSync('.stem-tutor-backups',{recursive:true});const backup=fs.mkdtempSync('.stem-tutor-backups/canvas-first-paint-'),originals=new Map();
for(const file of changed){const old=fs.existsSync(file)?fs.readFileSync(file):null;originals.set(file,old);if(old!==null){const copy=path.join(backup,file);fs.mkdirSync(path.dirname(copy),{recursive:true});fs.writeFileSync(copy,old);}}
fs.writeFileSync(path.join(backup,'manifest.json'),JSON.stringify(changed.map(file=>({file,existed:originals.get(file)!==null})),null,2));
try{for(const file of changed){fs.mkdirSync(path.dirname(file),{recursive:true});fs.writeFileSync(file,files[file],'utf8');}}catch(error){for(const [file,old]of originals){if(old===null){if(fs.existsSync(file))fs.unlinkSync(file);}else fs.writeFileSync(file,old);}console.error('Write failed; originals restored: '+error.message);process.exit(1);}
console.log('Installed '+changed.length+' files: stopped/paused canvas redraw fixes and a collapsible AI prompt (minimized by default).');
console.log('Backup: '+backup);
console.log('No packages, keys, header menus, or accessibility preferences were changed.');
console.log('Restart your dev server: npm run dev');
console.log('Checks: node checks/projectile-resize.cjs && npm run build');
